function earthLabels(){if(EARTH_DATA._a)return EARTH_DATA._a;const b=atob(EARTH_DATA.near),a=new Uint8Array(EARTH_DATA.w*EARTH_DATA.h);let k=0;for(let i=0;i<b.length;i+=2){const v=b.charCodeAt(i),n=b.charCodeAt(i+1);a.fill(v,k,k+n);k+=n}EARTH_DATA._a=a;return a}
function earthLabelAt(px,py){const a=earthLabels(),W=EARTH_DATA.w,H=EARTH_DATA.h;const x=Math.min(W-1,Math.max(0,Math.floor(px/MW*W))),y=Math.min(H-1,Math.max(0,Math.floor(py/MH*H)));return a[y*W+x]}
function earthMask(W,H){const m=new Float32Array(W*H),a=earthLabels(),EW=EARTH_DATA.w,EH=EARTH_DATA.h;for(let y=0;y<H;y++)for(let x=0;x<W;x++){const v=a[Math.floor(y/H*EH)*EW+Math.floor(x/W*EW)];m[y*W+x]=v>0&&v<128?1:0}
  const t=new Float32Array(W*H);for(let it=0;it<2;it++){for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){const i=y*W+x;t[i]=(m[i]*4+m[i-1]+m[i+1]+m[i-W]+m[i+W])/8}m.set(t)}return m}
